WITH kept_keys AS (SELECT channel, id FROM promotions INTERSECT ALL SELECT channel, id FROM promotions WHERE starts_on < '2025-07-27'), verified AS (SELECT s.* FROM promotions s INNER JOIN kept_keys k ON s.channel = k.channel AND s.id = k.id) SELECT CASE WHEN discount_pct >= 0.33 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_tier, DATE_TRUNC('MONTH', starts_on) AS activity_month, SUM(CASE WHEN promo_code = 'SPRING10' THEN discount_pct ELSE 0 END) AS spring10_discount_pct, SUM(CASE WHEN channel = 'web' THEN discount_pct ELSE 0 END) AS web_discount_pct, COUNT(*) AS num_rows, SUM(CASE WHEN channel = 'web' THEN discount_pct ELSE 0 END) AS web_discount_pct_2 FROM verified GROUP BY discount_pct_tier, activity_month HAVING web_discount_pct < 1000000;
